import xml.etree.ElementTree as ET

W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
NS = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

tree = ET.parse('unpacked/word/document.xml')
root = tree.getroot()

def para_text(p):
    return ''.join((t.text or '') for t in p.iter(W + 't'))

def run_info(r):
    rPr = r.find(W + 'rPr')
    info = []
    if rPr is not None:
        for child in rPr:
            tag = child.tag.replace(W, '')
            val = child.get(W + 'val')
            info.append(tag if val is None else f'{tag}={val}')
    text = ''.join((t.text or '') for t in r.iter(W + 't'))
    return ','.join(info), text

for i, p in enumerate(root.iter(W + 'p')):
    text = para_text(p)
    if not text.strip():
        continue
    runs = p.findall(W + 'r')
    fmt = [run_info(r) for r in runs]
    print(f'--- para {i} ---')
    for f, t in fmt:
        print(f'  rPr: [{f}] text: {t[:60]!r}')

import os
import xml.dom.minidom as minidom

XML_PATH = 'unpacked/word/document.xml'

doc = minidom.parse(XML_PATH)


def text_of(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild and t.firstChild.nodeType == t.TEXT_NODE:
            parts.append(t.firstChild.data)
    return ''.join(parts)


def is_headline(text):
    s = text.strip()
    if not s or len(s) > 80:
        return False
    has_cased = any(ch.isalpha() for ch in s)
    return has_cased and s.isupper()


# CT_RPr child element order per OOXML schema (ST_OnOff entries omitted here)
RPR_ORDER = ['rStyle', 'rFonts', 'b', 'bCs', 'i', 'iCs', 'caps', 'smallCaps', 'strike',
             'dstrike', 'outline', 'shadow', 'emboss', 'imprint', 'noProof', 'snapToGrid',
             'vanish', 'webHidden', 'color', 'spacing', 'w', 'kern', 'position', 'sz',
             'szCs', 'highlight', 'u', 'effect', 'bdr', 'shd', 'fitText', 'vertAlign',
             'rtl', 'cs', 'em', 'lang', 'eastAsianLayout', 'specVanish', 'oMath']


def add_underline(rPr):
    for n in [n for n in rPr.childNodes
              if n.nodeType == n.ELEMENT_NODE and n.tagName == 'w:u']:
        rPr.removeChild(n)
    u = rPr.ownerDocument.createElement('w:u')
    u.setAttribute('w:val', 'single')
    idx = RPR_ORDER.index('u')
    insert_before = None
    for child in rPr.childNodes:
        if child.nodeType == child.ELEMENT_NODE:
            local = child.tagName.split(':')[-1]
            if local in RPR_ORDER and RPR_ORDER.index(local) > idx:
                insert_before = child
                break
    if insert_before is not None:
        rPr.insertBefore(u, insert_before)
    else:
        rPr.appendChild(u)


headlines = []
for p in doc.getElementsByTagName('w:p'):
    t = text_of(p)
    if is_headline(t):
        headlines.append((p, t))

run_count = 0
for p, t in headlines:
    for r in p.getElementsByTagName('w:r'):
        rPrs = r.getElementsByTagName('w:rPr')
        if rPrs:
            rPr = rPrs[0]
        else:
            rPr = doc.createElement('w:rPr')
            r.insertBefore(rPr, r.firstChild)
        add_underline(rPr)
        run_count += 1

with open(XML_PATH, 'w', encoding='utf-8') as f:
    doc.writexml(f, encoding='utf-8', newl='\n')

# Remove the temporary pretty-print artifact so it isn't packed into the docx
stray = 'unpacked/word/document_pretty.xml'
if os.path.exists(stray):
    os.remove(stray)

print('headlines underlined:', len(headlines))
for _, t in headlines:
    print('  -', t)
print('runs updated:', run_count)

